for name,func,marker,early,countcheck in scripts:
 p=root/"benchmark"/"scripts"/(name+".py"); source=p.read_text(); baseline=run(p); entry={"script":str(p.relative_to(root)),"probe":"unchanged --check; LABVIEW_ENVIRONMENT unset","exit":baseline.returncode,"stdout":baseline.stdout,"stderr":baseline.stderr}; results.append(entry); print(json.dumps(entry)); variants={};
 if name=="change_cases":
  old="assert str(exc) == reason, (reason, str(exc))"; variants["first-character"]=source.replace(old,"assert str(exc)[:1] == reason[:1], (reason, str(exc))",1); variants["prefix"]=source.replace(old,"assert str(exc)[:len(reason)] == reason[:len(str(exc))], (reason, str(exc))",1); variants["prefix"]=source.replace(old,"assert reason.startswith(str(exc)), (reason, str(exc))",1)
 else:
