 assert source.count(marker)==1 and source.count(countcheck)==1; variants["early-return"]=source.replace(marker,early+marker,1); variants["early-return-plus-remove-caller-count"]=variants["early-return"].replace(countcheck,"",1); variants["remove-caller-count-only"]=source.replace(countcheck,"",1)
 for label,changed in variants.items():
  assert changed!=source; tree=ast.parse(changed); futures=[n.end_lineno for n in tree.body if isinstance(n,ast.ImportFrom) and n.module=="__future__"]; insertion=max(futures,default=0); lines=changed.splitlines(keepends=True); lines.insert(insertion,"__file__ = "+repr(str(p))+"\n"); target=td/(name+"-"+label+".py"); target.write_text("".join(lines)); output=run(target); entry={"script":str(p.relative_to(root)),"probe":label,"exit":output.returncode,"stdout":output.stdout,"stderr":output.stderr}; results.append(entry); print(json.dumps(entry))
art=root/".session"/"artifacts"; art.mkdir(parents=True,exist_ok=True); evidence={"method":"Temporary script copies set __file__ to the original script path before initialization, retaining original data paths. Repository scripts and JSON bodies were not modified or displayed. Prefix probes accept expected.startswith(actual). Early return reports zero completed reason self-tests. All runs unset LABVIEW_ENVIRONMENT.","results":results}; (art/"reason-controls-probes.json").write_text(json.dumps(evidence,indent=2)+"\n"); print("EVIDENCE .session/artifacts/reason-controls-probes.json"); print("FINAL STATUS",subprocess.run(["git","status","--short"],capture_output=True,text=True).stdout); temp.cleanup()'
